def historyThrough {I : Type*} [LinearOrder I] {D : I → Type*}
    (fallback : ∀ i, D i) (a : I) (f : ∀ j, j < a → D j) (x : D a) : ∀ i, D i :=
  Function.update (fun j => if h : j < a then f j h else fallback j) a x

